'use server';

import { revalidatePath } from 'next/cache';
import { createClient } from '@/lib/supabase-server';
import { createAdminClient } from '@/lib/supabase-admin';
import { createPromptAvatar, heygenConfigured } from '@/lib/heygen';

// The platform presenter (Ayman's decision 2026-11-07: a stock/AI face,
// not his own photo). Generated by HeyGen from this prompt at 9:16 so
// the avatar's SOURCE is natively portrait — the property the whole
// public catalog lacked (final census, 2026-11-07). Depicts no real
// person, so no consent step applies.
const PRESENTER_NAME = 'HubElites Presenter (AI)';
const PRESENTER_PROMPT =
  'Photorealistic head-and-shoulders portrait of a friendly professional woman in her late thirties with shoulder-length dark brown hair, a warm confident smile, wearing a navy blazer over a white top, in a bright modern office with a softly blurred background, looking directly at the camera, natural skin texture, studio-quality lighting, vertical portrait composition.';

async function requireSuperAdmin() {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return null;
  const { data: profile } = await supabase.from('profiles').select('is_super_admin').eq('id', user.id).maybeSingle();
  return profile?.is_super_admin ? user : null;
}

export async function createPresenter(): Promise<{ ok: boolean; error?: string }> {
  const user = await requireSuperAdmin();
  if (!user) return { ok: false, error: 'Super admin session required.' };
  if (!heygenConfigured()) return { ok: false, error: 'HeyGen is not configured.' };
  try {
    const look = await createPromptAvatar({ name: PRESENTER_NAME, prompt: PRESENTER_PROMPT });
    const admin = createAdminClient();
    const { data: row } = await admin
      .from('media_provider_catalog')
      .select('id, config')
      .eq('provider', 'heygen')
      .maybeSingle();
    if (row) {
      const config = { ...((row.config as Record<string, unknown>) ?? {}), presenter_look_id: look.id, presenter_name: PRESENTER_NAME };
      await admin.from('media_provider_catalog').update({ config }).eq('id', row.id);
    }
    revalidatePath('/admin/presenter');
    return { ok: true };
  } catch (error) {
    return { ok: false, error: error instanceof Error ? error.message : 'Presenter creation failed.' };
  }
}
